package dojo.jpa.l1.mapping;

import java.time.Instant;

/**
 * KATA jpa L1 "Mapping" (tracks/08-jpa-transactions/L1-basics.md, sections 2-3).
 *
 * Map this class and PurchaseOrder to the tables jpa_customer and jpa_purchase_order in
 * src/main/resources/db/migration/V1__jpa_katas.sql (Hibernate validates the mapping at startup):
 * - id generated by the database (identity column);
 * - fullName -> column full_name; createdAt -> created_at;
 * - tier stored as its NAME ('GOLD'), not as a number (what happens to numbers when someone
 *   reorders the enum?);
 * JPA needs a no-argument constructor (it can be protected). Do not change the public API.
 */
public class Customer {

	private Long id;
	private String fullName;
	private String email;
	private Tier tier;
	private Instant createdAt;

	protected Customer() {
	}

	public Customer(String fullName, String email, Tier tier) {
		this.fullName = fullName;
		this.email = email;
		this.tier = tier;
		this.createdAt = Instant.now();
	}

	public Long getId() {
		return id;
	}

	public String getFullName() {
		return fullName;
	}

	public String getEmail() {
		return email;
	}

	public Tier getTier() {
		return tier;
	}

	public void upgrade() {
		this.tier = Tier.GOLD;
	}

}
